# libco development image with clang and coverage support
FROM ubuntu:22.04

# Install dependencies
RUN apt-get update && apt-get install -y \
    clang \
    llvm \
    lld \
    make \
    cmake \
    g++ \
    git \
    python3 \
    && rm -rf /var/lib/apt/lists/*

# Set clang as default compiler
ENV CC=clang
ENV CXX=clang++
ENV AR=llvm-ar
ENV RANLIB=llvm-ranlib

# Create workspace directory
WORKDIR /workspace

# Copy libco source code
COPY libco /workspace/libco

WORKDIR /workspace/libco

# Build libco with coverage support using clang
# Coverage flags: -fprofile-instr-generate -fcoverage-mapping
RUN mkdir -p install && \
    clang++ -c -g -O0 -fPIC \
    -fprofile-instr-generate -fcoverage-mapping \
    -D_GNU_SOURCE -D_REENTRANT -Wall -pipe \
    co_epoll.cpp \
    co_routine.cpp \
    co_hook_sys_call.cpp \
    coctx.cpp \
    co_comm.cpp \
    -I. && \
    clang -c -g -O0 -fPIC \
    -fprofile-instr-generate -fcoverage-mapping \
    -D_GNU_SOURCE -D_REENTRANT -Wall -pipe \
    coctx_swap.S && \
    llvm-ar rcs install/libco.a \
    co_epoll.o \
    co_routine.o \
    co_hook_sys_call.o \
    coctx.o \
    co_comm.o \
    coctx_swap.o

# Create unit test for co_resume
RUN cat > /workspace/libco/install/ut_co_resume.cpp << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "co_routine.h"

// Global flag to track if coroutine executed
static int g_coroutine_executed = 0;
static int g_coroutine_result = 0;

// Test coroutine function
void* test_coroutine_func(void* arg)
{
    int value = *(int*)arg;
    g_coroutine_executed = 1;
    g_coroutine_result = value * 2;
    printf("Coroutine executed with arg=%d, result=%d\n", value, g_coroutine_result);
    co_yield_ct();
    printf("Coroutine resumed after yield\n");
    g_coroutine_result += 10;
    return NULL;
}

int main(int argc, char* argv[])
{
    printf("Starting co_resume unit test\n");

    stCoRoutine_t* co = NULL;
    int arg = 42;

    // Test 1: Create a coroutine
    printf("Test 1: Creating coroutine...\n");
    int ret = co_create(&co, NULL, test_coroutine_func, &arg);
    if (ret != 0 || co == NULL) {
        printf("FAILED: co_create failed with ret=%d\n", ret);
        return 1;
    }
    printf("PASSED: Coroutine created successfully\n");

    // Test 2: Resume the coroutine (first time - starts execution)
    printf("Test 2: Resuming coroutine (first time)...\n");
    g_coroutine_executed = 0;
    co_resume(co);
    if (!g_coroutine_executed) {
        printf("FAILED: Coroutine did not execute after co_resume\n");
        return 1;
    }
    if (g_coroutine_result != 84) {
        printf("FAILED: Coroutine result=%d, expected=84\n", g_coroutine_result);
        return 1;
    }
    printf("PASSED: Coroutine resumed and executed correctly\n");

    // Test 3: Resume the coroutine again (after yield)
    printf("Test 3: Resuming coroutine (after yield)...\n");
    co_resume(co);
    if (g_coroutine_result != 94) {
        printf("FAILED: Coroutine result=%d, expected=94 after second resume\n", g_coroutine_result);
        return 1;
    }
    printf("PASSED: Coroutine resumed after yield correctly\n");

    // Test 4: Resume completed coroutine
    printf("Test 4: Resuming completed coroutine...\n");
    co_resume(co);
    printf("PASSED: Resuming completed coroutine handled gracefully\n");

    // Test 5: Create and resume multiple coroutines
    printf("Test 5: Testing multiple coroutines...\n");
    stCoRoutine_t* co2 = NULL;
    int arg2 = 10;
    ret = co_create(&co2, NULL, test_coroutine_func, &arg2);
    if (ret != 0) {
        printf("FAILED: Second co_create failed\n");
        return 1;
    }
    g_coroutine_executed = 0;
    g_coroutine_result = 0;
    co_resume(co2);
    if (!g_coroutine_executed || g_coroutine_result != 20) {
        printf("FAILED: Second coroutine execution failed\n");
        return 1;
    }
    printf("PASSED: Multiple coroutines work correctly\n");

    // Cleanup
    printf("Cleaning up...\n");
    co_release(co);
    co_release(co2);

    printf("\n========================================\n");
    printf("All co_resume unit tests PASSED!\n");
    printf("========================================\n");

    return 0;
}
EOF

# Compile the unit test
RUN clang++ -o install/ut_co_resume \
    install/ut_co_resume.cpp \
    -I. \
    install/libco.a \
    -fprofile-instr-generate -fcoverage-mapping \
    -lpthread -ldl

# Copy header files to install directory for reference
RUN cp co_routine.h install/

# Set default working directory
WORKDIR /workspace/libco

# Default command
CMD ["/bin/bash"]

